Lemma mu_running p s : halted s = false ->
  mu p s = (blen p - s_pos s) * 2 ^ 27 + 4 * wsum (s_stk s) + 2 * fsum (s_stk s) + Z.of_nat (length (s_stk s)) + 1.
Proof.
